`resetall
`timescale 1ns/1ps

module pipe_reg_4e2b338015fa4dcf90db98e59028572b
#(parameter 
  DEPTH = 32,
  WIDTH = 4)
(// output
 output wire [WIDTH-1:0] d_o,
 // input
 input [WIDTH-1:0] d_i,
 input clk_i);

reg [WIDTH-1:0] pipe_reg_4e2b338015fa4dcf90db98e59028572b [DEPTH-1:0];
integer i;

always @(posedge clk_i) begin :rtlPipeBit
  for (i=DEPTH-1; i>0; i = i - 1) begin
    pipe_reg_4e2b338015fa4dcf90db98e59028572b[i] <= pipe_reg_4e2b338015fa4dcf90db98e59028572b[i-1];
  end
  pipe_reg_4e2b338015fa4dcf90db98e59028572b[0] <= d_i;
end
assign d_o = pipe_reg_4e2b338015fa4dcf90db98e59028572b[DEPTH-1];
   

endmodule

